const record=(kind,d)=>events.push({kind,target:d?.target,reason:d?.reason,action:d?.action,id:d?.id,index:d?.index,collection:d?.collection,value:d?.value}),onAction=d=>{record('action',d);if(!accept)return;if(d.target==='button.menu_network_join_by_code')setJoinOpen(true);if(d.target==='server_navigation_toggle'){setSelected(d.id??'add');setDetailsKind(d.index===100?'add':d.collection==='servers_network_worlds'?'additional':'featured');}};
const navigation={...data.navigation,value:tab,friends:friendsIndicators,disabled,onValueChange:value=>{events.push({kind:'tab',value});if(accept)setTab(value);}},size=[270,212],shared={scale:2,inputMode,disabled,readOnly,onAction};
const featured=data.servers.featured.map(item=>({...item,selected:item.id===selected})),additional=data.servers.additional.map(item=>({...item,selected:item.id===selected}));
const p={...data,navigation,inputMode,exitButtonVisible:exitVisible,worlds:{...data.worlds,flags:worldsFlags,disabled,readOnly,onAction},friends:{...data.friends,flags:friendsFlags,disabled,readOnly,onAction},servers:{...data.servers,featured,additional,visibility:{...serverVisibility,addServerSelected:detailsKind==='add'},details:{...data.servers.details,featuredVisible:detailsKind==='featured',additionalVisible:detailsKind==='additional',addVisible:detailsKind==='add'},disabled,readOnly,onAction},popups:{joinByCode:{...data.popups.joinByCode,open:joinOpen,value:code,disabled,readOnly,inputRef:refs.codeInput,closeRef:refs.popupClose,onValueChange:value=>{events.push({kind:'code',value});if(accept)setCode(value);},onAction:d=>record('join-code',d),onClose:d=>{record('close-code',d);if(accept)setJoinOpen(false);}},highPing:{...data.popups.highPing,open:highOpen,disabled,readOnly,onAction:d=>{record('ping',d);if(accept&&d.action==='cancel')setHighOpen(false);},onClose:d=>{record('close-ping',d);if(accept)setHighOpen(false);}}},onExitRequest:d=>{record('exit',d);return false;}};
window.playInstalled={react:React.version,runtimeValues:Object.keys(ui).length,refs,events,tab,inputMode,accept,readOnly,disabled,exitVisible,joinOpen,highOpen,code,selected,detailsKind,setTab,setInputMode,setAccept,setReadOnly,setDisabled,setExitVisible,setJoinOpen,setHighOpen,setCode,setWorldsFlags,setFriendsFlags,setServerVisibility,setFriendsIndicators,clear(){events.length=0;},unmount,mount};
