 const files={'index.html':html,'main.jsx':browserApp,'play-data.json':JSON.stringify(data.value,null,2)+'\n'},pins={};for(const[name,text]of Object.entries(files)){await fs.writeFile(path.join(directory,name),text,{flag:'wx'});pins[name]=hash(Buffer.from(text));}
